CREATE SCHEMA fhir;

CREATE USER [ericpasztor@microsoft.com] FROM EXTERNAL PROVIDER; 

EXEC sp_addrolemember 'largerc', 'ericpasztor@microsoft.com';

CREATE WORKLOAD GROUP wgDataLoads
   WITH ( 
       MIN_PERCENTAGE_RESOURCE = 0
       ,CAP_PERCENTAGE_RESOURCE = 100
       ,REQUEST_MIN_RESOURCE_GRANT_PERCENT = 100
	);

   CREATE WORKLOAD CLASSIFIER wgETLAdmin
   WITH (
	     WORKLOAD_GROUP = 'wgDataLoads'
       , MEMBERNAME = 'ericpasztor@microsoft.com'
      , IMPORTANCE = ABOVE_NORMAL
   );

SELECT  r.name AS [Resource Class]
,       m.name AS membername
FROM    sys.database_role_members rm
JOIN    sys.database_principals AS r ON rm.role_principal_id = r.principal_id
JOIN    sys.database_principals AS m ON rm.member_principal_id = m.principal_id
WHERE   r.name IN ('mediumrc','largerc','xlargerc','staticrc10','staticrc20','staticrc30','staticrc40','staticrc50','staticrc60','staticrc70','staticrc80');

